

import { useEffect, useState } from "react";
import "./App.css";

const initialLifts = [
  { id: "LFT-001", customer: "ABC Residence", location: "Tower A", model: "Passenger", status: "Active" },
    { id: "LFT-002", customer: "City Centre", location: "Tower B", model: "Passenger", status: "Active" },
      { id: "LFT-003", customer: "Green Plaza", location: "Block 1", model: "Goods", status: "Inspection due" },
      ];

      const initialJobs = [
        { id: "JOB-001", lift: "LFT-001", type: "Monthly maintenance", technician: "Technician 1", status: "Pending" },
          { id: "JOB-002", lift: "LFT-002", type: "Breakdown call", technician: "Technician 2", status: "In progress" },
            { id: "JOB-003", lift: "LFT-003", type: "Safety inspection", technician: "Technician 1", status: "Completed" },
            ];

            const checklistItems = [
              "Machine room inspection",
                "Door operation and interlocks",
                  "Landing doors and car doors",
                    "Alarm and emergency communication",
                      "Levelling and ride quality",
                        "Safety devices and final checks",
                        ];

                        export default function App() {
                          const [page, setPage] = useState("Dashboard");
                            
const [lifts, setLifts] = useState(() => {
  try {
    const saved = localStorage.getItem("lsms-lifts");
    return saved ? JSON.parse(saved) : initialLifts;
  } catch {
    return initialLifts;
  }
});

const [jobs, setJobs] = useState(() => {
  try {
    const saved = localStorage.getItem("lsms-jobs");
    return saved ? JSON.parse(saved) : initialJobs;
  } catch {
    return initialJobs;
  }
});

useEffect(() => {
  try {
    localStorage.setItem("lsms-lifts", JSON.stringify(lifts));
  } catch (error) {
    console.error("Could not save lifts:", error);
  }
}, [lifts]);

useEffect(() => {
  try {
    localStorage.setItem("lsms-jobs", JSON.stringify(jobs));
  } catch (error) {
    console.error("Could not save jobs:", error);
  }
}, [jobs]);

useEffect(() => {
  try {
    localStorage.setItem("lsms-lifts", JSON.stringify(lifts));
  } catch (error) {
    console.error("Could not save lifts:", error);
  }
}, [lifts]);

useEffect(() => {
  try {
    localStorage.setItem("lsms-jobs", JSON.stringify(jobs));
  } catch (error) {
    console.error("Could not save jobs:", error);
  }
}, [jobs]);

                                const [checks, setChecks] = useState({});
                                  const [liftForm, setLiftForm] = useState(false);
                                    const [jobForm, setJobForm] = useState(false);
                                      const [newLift, setNewLift] = useState({ customer: "", location: "", model: "Passenger" });
                                        const [newJob, setNewJob] = useState({ lift: "LFT-001", type: "Monthly maintenance", technician: "" });
                                          const [report, setReport] = useState(null);

                                            const completed = jobs.filter(j => j.status === "Completed").length;
                                              const pending = jobs.filter(j => j.status === "Pending").length;
                                                const active = jobs.filter(j => j.status === "In progress").length;

                                                  function addLift(e) {
                                                      e.preventDefault();
                                                          if (!newLift.customer.trim() || !newLift.location.trim()) return;
                                                              setLifts([...lifts, {
                                                                    id: `LFT-${String(lifts.length + 1).padStart(3, "0")}`,
                                                                          ...newLift,
                                                                                status: "Active",
                                                                                    }]);
                                                                                        setNewLift({ customer: "", location: "", model: "Passenger" });
                                                                                            setLiftForm(false);
                                                                                              }

                                                                                                function addJob(e) {
                                                                                                    e.preventDefault();
                                                                                                        if (!newJob.technician.trim()) return;
                                                                                                            setJobs([...jobs, {
                                                                                                                  id: `JOB-${String(jobs.length + 1).padStart(3, "0")}`,
                                                                                                                        ...newJob,
                                                                                                                              status: "Pending",
                                                                                                                                  }]);
                                                                                                                                      setNewJob({ lift: lifts[0]?.id || "", type: "Monthly maintenance", technician: "" });
                                                                                                                                          setJobForm(false);
                                                                                                                                            }

                                                                                                                                              function changeStatus(id, status) {
                                                                                                                                                  setJobs(jobs.map(j => j.id === id ? { ...j, status } : j));
                                                                                                                                                    }

                                                                                                                                                      const nav = [
                                                                                                                                                          ["Dashboard", "▦"],
                                                                                                                                                              ["Lift Register", "▤"],
                                                                                                                                                                  ["Service Jobs", "🔧"],
                                                                                                                                                                      ["Checklist", "☑"],
                                                                                                                                                                          ["Reports", "▧"],
                                                                                                                                                                            ];

                                                                                                                                                                              return (
                                                                                                                                                                                  <div className="app">
                                                                                                                                                                                        <header className="topbar">
                                                                                                                                                                                                <div className="brand-mark">L</div>
                                                                                                                                                                                                        <div className="brand">
                                                                                                                                                                                                                  <strong>Lift Dynamics<span>LSMS</span></strong>
                                                                                                                                                                                                                            <small>Lift Service Management</small>
                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                            <div className="user-badge">AD</div>
                                                                                                                                                                                                                                                  </header>

                                                                                                                                                                                                                                                        <div className="workspace">
                                                                                                                                                                                                                                                                <aside className="sidebar">
                                                                                                                                                                                                                                                                          <p className="nav-label">WORKSPACE</p>
                                                                                                                                                                                                                                                                                    {nav.map(([name, icon]) => (
                                                                                                                                                                                                                                                                                                <button key={name} onClick={() => setPage(name)}
                                                                                                                                                                                                                                                                                                              className={`nav-item ${page === name ? "selected" : ""}`}>
                                                                                                                                                                                                                                                                                                                            <span>{icon}</span>{name}
                                                                                                                                                                                                                                                                                                                                        </button>
                                                                                                                                                                                                                                                                                                                                                  ))}
                                                                                                                                                                                                                                                                                                                                                            <div className="side-note">
                                                                                                                                                                                                                                                                                                                                                                        <strong>LSMS Phase 1</strong>
                                                                                                                                                                                                                                                                                                                                                                                    <p>Maintenance made simple.</p>
                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                      </aside>

                                                                                                                                                                                                                                                                                                                                                                                                              <main className="main">
                                                                                                                                                                                                                                                                                                                                                                                                                        <div className="mobile-nav">
                                                                                                                                                                                                                                                                                                                                                                                                                                    {nav.map(([name, icon]) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                  <button key={name} onClick={() => setPage(name)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  className={page === name ? "mobile-active" : ""}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <span>{icon}</span><small>{name === "Lift Register" ? "Lifts" : name === "Service Jobs" ? "Jobs" : name}</small>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="page-heading">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <p className="eyebrow">LIFT SERVICE MANAGEMENT SYSTEM</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <h1>{page}</h1>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <p className="subtitle">Manage your lift maintenance operations.</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {page === "Lift Register" && <button className="primary" onClick={() => setLiftForm(!liftForm)}>+ Add lift</button>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {page === "Service Jobs" && <button className="primary" onClick={() => setJobForm(!jobForm)}>+ Create job</button>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {page === "Dashboard" && <>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="welcome">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div><p className="welcome-tag">OPERATIONS OVERVIEW</p><h2></h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <p>Here is your service activity at a glance.</p><h1>Welcome to Lift Dynamics</h1></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div className="welcome-icon">⚙</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="stats">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Stat label="Registered lifts" value={lifts.length} icon="▤" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <Stat label="Pending jobs" value={pending} icon="◷" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Stat label="In progress" value={active} icon="🔧" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <Stat label="Completed jobs" value={completed} icon="✓" />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <section className="panel">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="panel-heading"><div><h2>Recent service jobs</h2><p>Latest work orders and their status</p></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button className="text-button" onClick={() => setPage("Service Jobs")}>View all →</button></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <JobTable jobs={jobs.slice(0, 5)} onStatus={changeStatus} onReport={setReport} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </section>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <section className="panel">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="panel-heading"><div><h2>Maintenance overview</h2><p>Current lift register status</p></div></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="overview-row"><span>Registered lifts</span><strong>{lifts.length}</strong></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="overview-row"><span>Inspection due</span><strong>{lifts.filter(l => l.status === "Inspection due").length}</strong></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="overview-row"><span>Jobs awaiting assignment</span><strong>{jobs.filter(j => !j.technician.trim()).length}</strong></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </section>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </>}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {page === "Lift Register" && <>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {liftForm && <form className="panel form" onSubmit={addLift}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <h2>Register a lift</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <label>Customer / building<input required value={newLift.customer} onChange={e => setNewLift({...newLift, customer:e.target.value})} placeholder="e.g. ABC Residence" /></label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <label>Location<input required value={newLift.location} onChange={e => setNewLift({...newLift, location:e.target.value})} placeholder="e.g. Tower A" /></label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <label>Lift type<select value={newLift.model} onChange={e => setNewLift({...newLift, model:e.target.value})}><option>Passenger</option><option>Goods</option><option>Service</option><option>Escalator</option></select></label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <button className="primary">Save lift</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </form>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <section className="panel"><div className="panel-heading"><div><h2>Customer and lift register</h2><p>{lifts.length} registered assets</p></div></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="table-wrap"><table><thead><tr><th>Lift ID</th><th>Customer</th><th>Location</th><th>Type</th><th>Status</th></tr></thead>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <tbody>{lifts.map(l => <tr key={l.id}><td><strong>{l.id}</strong></td><td>{l.customer}</td><td>{l.location}</td><td>{l.model}</td><td><Status value={l.status} /></td></tr>)}</tbody>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </table></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </section>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </>}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {page === "Service Jobs" && <>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {jobForm && <form className="panel form" onSubmit={addJob}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <h2>Create a service job</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <label>Lift<select value={newJob.lift} onChange={e => setNewJob({...newJob,lift:e.target.value})}>{lifts.map(l => <option key={l.id} value={l.id}>{l.id} — {l.customer}</option>)}</select></label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <label>Job type<select value={newJob.type} onChange={e => setNewJob({...newJob,type:e.target.value})}><option>Monthly maintenance</option><option>Breakdown call</option><option>Safety inspection</option><option>Repair work</option></select></label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <label>Assigned technician<input required value={newJob.technician} onChange={e => setNewJob({...newJob,technician:e.target.value})} placeholder="Technician name" /></label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <button className="primary">Create job</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </form>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <section className="panel"><div className="panel-heading"><div><h2>Service work orders</h2><p>{jobs.length} total jobs</p></div></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <JobTable jobs={jobs} onStatus={changeStatus} onReport={setReport} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </section>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </>}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {page === "Checklist" && <>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <section className="panel">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="panel-heading"><div><h2>Preventive maintenance checklist</h2><p>Demonstration checklist — select items inspected</p></div></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <label className="field-label">Select lift</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <select className="standalone-select" value={checks.lift || lifts[0]?.id || ""} onChange={e => setChecks({...checks,lift:e.target.value})}>{lifts.map(l => <option key={l.id} value={l.id}>{l.id} — {l.customer}</option>)}</select>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="checklist">{checklistItems.map((item,i) => <label className="check-row" key={item}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <input type="checkbox" checked={!!checks[i]} onChange={e => setChecks({...checks,[i]:e.target.checked})} /><span>{item}</span><small>{checks[i] ? "Checked" : "Pending"}</small>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </label>)}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <label className="field-label">Technician notes</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <textarea className="notes" placeholder="Record observations, defects and follow-up work..." value={checks.notes || ""} onChange={e => setChecks({...checks,notes:e.target.value})} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <button className="primary" onClick={() => window.alert("Checklist state is saved for this session only. Database storage will be added later.")}>Save checklist</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </section>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </>}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {page === "Reports" && <>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <section className="panel"><div className="panel-heading"><div><h2>Service reports</h2><p>Review work orders and prepare report details</p></div></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div className="stats report-stats"><Stat label="Total jobs" value={jobs.length} icon="▤" /><Stat label="Completed" value={completed} icon="✓" /></div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <JobTable jobs={jobs.filter(j => j.status === "Completed")} onStatus={changeStatus} onReport={setReport} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {report && <div className="report-detail"><h2>Service report preview</h2><p><strong>Job:</strong> {report.id}</p><p><strong>Lift:</strong> {report.lift}</p><p><strong>Work:</strong> {report.type}</p><p><strong>Technician:</strong> {report.technician || "Not assigned"}</p><p><strong>Status:</strong> {report.status}</p><button className="primary" onClick={() => window.print()}>Print / Save PDF</button></div>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </section>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </>}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <footer>Lift Dynamics LSMS · Phase 1 prototype · Sample data only</footer>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </main>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function Stat({label, value, icon}) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return <div className="stat-card"><div className="stat-top"><span>{label}</span><b>{icon}</b></div><strong className="stat-value">{value}</strong></div>;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function Status({value}) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const cls = value === "Completed" || value === "Active" ? "good" : value === "In progress" ? "working" : "waiting";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return <span className={`status ${cls}`}>{value}</span>;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function JobTable({jobs, onStatus, onReport}) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!jobs.length) return <p className="empty">No jobs to display yet.</p>;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return <div className="table-wrap"><table><thead><tr><th>Job ID</th><th>Lift</th><th>Work type</th><th>Technician</th><th>Status</th><th>Actions</th></tr></thead>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <tbody>{jobs.map(j => <tr key={j.id}><td><strong>{j.id}</strong></td><td>{j.lift}</td><td>{j.type}</td><td>{j.technician || "Unassigned"}</td><td><Status value={j.status} /></td><td><div className="actions"><select aria-label={`Update ${j.id} status`} value={j.status} onChange={e => onStatus(j.id,e.target.value)}><option>Pending</option><option>In progress</option><option>Completed</option></select><button className="small-button" onClick={() => onReport(j)}>Report</button></div></td></tr>)}</tbody>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </table></div>;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              